mapper.select:
SELECT *, d.name AS dept_name, r.name AS role_name FROM user AS u LEFT JOIN role AS r ON u.role_id = r.id LEFT JOIN dept AS d ON u.dept_id = d.id
AND u.name LIKE CONCAT('%', #{userDTO.name}, '%')
AND u.status = #{userDTO.status}
AND u.phone LIKE CONCAT('%', #{userDTO.phone}, '%')
AND u.dept_id = #{userDTO.deptId}
ORDER BY u.create_time DESC
